import{_ as e,c as s,o as a,a3 as o}from"./chunks/framework.Dokpd4od.js";const d=JSON.parse('{"title":"Applicant list","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/applicants/applicant-list.md","filePath":"master/human-resources/recruitment/applicants/applicant-list.md","lastUpdated":1791902625000}'),n={name:"master/human-resources/recruitment/applicants/applicant-list.md"};function r(i,t,l,p,c,g){return a(),s("div",null,t[0]||(t[0]=[o('<h1 id="applicant-list" tabindex="-1">Applicant list <a class="header-anchor" href="#applicant-list" aria-label="Permalink to &quot;Applicant list&quot;">​</a></h1><p>The applicant list shows every application in one table. You use it to find people, see who is in which stage, and open an applicant. Tabs, grouping, filters and columns let you answer questions such as &quot;Who is in the second interview?&quot;.</p><blockquote><p><strong>In simple words:</strong> One table of all applications, grouped by stage. Use tabs and filters to narrow it down.</p></blockquote><p>Open <code>Recruitments → Applications → Applicants</code>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page title is <strong>Applicants</strong>. <strong>New Applicant</strong> at the top right creates an application. See <a href="./add-applicant.html">Add an applicant</a>. Under the title you see the tabs, then the search box, the filter icon, the column icon and the <strong>Group by</strong> selector.</p><p>Click a row to open the applicant. Each group header reads <strong>Stage: New</strong>, <strong>Stage: First Interview</strong> and so on. Click a header to collapse it.</p><h3 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h3><p>The tabs are saved views. The row of tabs shows five of them:</p><ul><li><strong>Default:</strong> all applicants, grouped by <strong>Stage</strong>.</li><li><strong>My Applicants:</strong> applicants where you are the recruiter.</li><li><strong>Un Assigned:</strong> applicants without a recruiter.</li><li><strong>In Progress:</strong> applicants still in the process.</li><li><strong>Archived:</strong> inactive applicants, such as refused ones.</li></ul><p>Click the three dots next to the tabs to see more views. Each has <strong>Apply View</strong> and <strong>Add to Favorites</strong>. Favorites show as tabs.</p><ul><li><strong>Hired:</strong> applicants who reached a hired stage.</li><li><strong>Refused:</strong> applicants with the refused status.</li><li><strong>Blocked:</strong> applicants whose state is blocked.</li><li><strong>Directly Available</strong>, <strong>Created Recently</strong> and <strong>Stage Updated Recently</strong>: extra views you can apply.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>In the sample data, <strong>My Applicants</strong>, <strong>Refused</strong>, <strong>Directly Available</strong>, <strong>Created Recently</strong> and <strong>Stage Updated Recently</strong> show no rows. A view shows rows only when applicants match it. For example, <strong>My Applicants</strong> lists applicants whose recruiter is you.</p></div><p>Use <strong>Add New</strong> in the same menu to save your own view. <strong>Reset</strong> returns to the standard views.</p><h2 id="group-the-list" tabindex="-1">Group the list <a class="header-anchor" href="#group-the-list" aria-label="Permalink to &quot;Group the list&quot;">​</a></h2><p><strong>Group by</strong> starts on <strong>Stage</strong>. Choose another value:</p><ul><li><strong>Job Position</strong></li><li><strong>Candidate Name</strong></li><li><strong>Responsible</strong></li><li><strong>Creation Date</strong></li><li><strong>Hired Date</strong></li><li><strong>Last Stage</strong></li><li><strong>Refuse Reason</strong></li></ul><p>Choose <code>-</code> for no grouping. Set the direction to <strong>Ascending</strong> or <strong>Descending</strong>.</p><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>Three columns show at first: <strong>Partner Name</strong>, <strong>Applied On</strong> and <strong>Job Position</strong>. Click the column icon to add more:</p><p><strong>Stage</strong>, <strong>Candidate Name</strong>, <strong>Application Status</strong>, <strong>Refuse Reason</strong>, <strong>Evaluation</strong>, <strong>Tags</strong>, <strong>Email</strong>, <strong>Recruiter</strong>, <strong>Interviewer</strong>, <strong>Phone</strong>, <strong>Medium</strong>, <strong>Source</strong>, <strong>Expected Salary</strong> and <strong>Availability Date</strong>.</p><h2 id="search-and-filters" tabindex="-1">Search and filters <a class="header-anchor" href="#search-and-filters" aria-label="Permalink to &quot;Search and filters&quot;">​</a></h2><p>Type in the search box to find an applicant. Click the funnel icon to build a filter. You can filter by:</p><p><strong>Source</strong>, <strong>Medium</strong>, <strong>Candidate</strong>, <strong>Last Stage Updated</strong>, <strong>Stage</strong>, <strong>Job Position</strong>, <strong>Priority</strong>, <strong>Applied On</strong> and <strong>Hired Date</strong>. Salary and <strong>Applicant Notes</strong> are also available.</p><p>See <a href="./../../../getting-started/search-filter-group.html">Search, filter and group</a> for how filters work.</p><h2 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h2><p>The kebab menu on a row has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>. The clock icon opens the activity action. See <a href="./../../../getting-started/chatter/actions/activity.html">Schedule an activity</a>. Select rows to delete several at once.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Blocked applicants do not show in the normal tabs. Apply the <strong>Blocked</strong> view to find them.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./process-applicant.html">Process an applicant</a></li><li><a href="./refuse-and-reopen.html">Refuse and reopen</a></li><li><a href="./../dashboard/recruitment-dashboard.html">Recruitment dashboard</a></li></ul>',30)]))}const u=e(n,[["render",r]]);export{d as __pageData,u as default};
